const o = ON[T.bg];
const words = ['เจ๊ง', 'ขาดทุน'];
for (let i = 0; i < 2; i++) {
  const y = 330 + i * 400;
  const w = div(`left:90px;top:${y}px;width:850px;height:260px;opacity:0;text-align:center;font-family:KeySans;font-size:200px;line-height:260px;color:${o.ink}`, c, words[i]);
  fitW(w, 800);
  mv.rise(w, T.t0 + .1 + i * .2);
  const x = svg(340, 260, `<path d='M30 20 L310 240' stroke='${RED}' stroke-width='34' stroke-linecap='round' fill='none'/><path d='M310 20 L30 240' stroke='${RED}' stroke-width='34' stroke-linecap='round' fill='none'/>`, `left:${340}px;top:${y}px`, c);
  const ps = x.querySelectorAll('path');
  const t = T.hit + i * .45;
  mv.draw(ps[0], t, .2);
  mv.draw(ps[1], t + .15, .2);
  mv.wobble(w, t + .3);
}
snd('hit', T.hit);
snd('pop', T.hit + .45);

const phone = div(`left:370px;top:360px;width:340px;height:620px;border:18px solid ${NAVY};border-radius:60px;opacity:0`, c);
mv.pop(phone, T.t0 + .1);
const cam = div('left:90px;top:200px;width:100px;height:100px;opacity:0', phone, ico('video', 100, NAVY, 2.5));
mv.show(cam, T.t0 + .3);
const dot = div(`left:130px;top:60px;width:44px;height:44px;border-radius:22px;background:${ACC};opacity:0`, phone);
mv.show(dot, T.t0 + .3);
mv.punch(dot, T.t0 + .5);
mv.punch(dot, T.t0 + 1);
const coin = div('left:600px;top:260px;width:230px;height:230px;opacity:0', c, ico('circle-dollar-sign', 230, ACC, 2.5));
mv.pop(coin, T.hit);
mv.float(coin, T.hit + .3, T.t1, 10);
mv.punch(phone, T.hit);
snd('hit', T.hit);

const o = ON[T.bg];
const big = tile(c, 'briefcase', T.t0 + .1, 'left:120px;top:380px', {size: 580, bg: o.tile, color: o.tileInk, sound: false, float: false});
mv.punch(big.inner, T.hit);
const coin = div('left:760px;top:790px;width:150px;height:150px;opacity:0', c, ico('circle-dollar-sign', 150, ACC, 2.5));
mv.pop(coin, T.hit);
mv.wobble(coin, T.hit + .3);
snd('hit', T.hit);
